package com.xuhang.mealops.inventory.api;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*; import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*; import java.util.*; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.*; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.context.annotation.Import; import org.springframework.http.MediaType; import org.springframework.test.web.servlet.*; import org.springframework.test.web.servlet.setup.MockMvcBuilders; import org.springframework.web.context.WebApplicationContext; import com.jayway.jsonpath.JsonPath; import com.xuhang.mealops.support.PostgresTestConfiguration;
@SpringBootTest @Import(PostgresTestConfiguration.class) class InventoryConsumptionApiIT { @Autowired WebApplicationContext context; MockMvc mvc; @BeforeEach void setup(){mvc=MockMvcBuilders.webAppContextSetup(context).build();} private long ingredient() throws Exception{var r=mvc.perform(post("/api/v1/ingredients").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"Consume "+UUID.randomUUID()+"\"}" )).andExpect(status().isCreated()).andReturn();return ((Number)JsonPath.read(r.getResponse().getContentAsString(),"$.id")).longValue();} @Test void consumesCanonicalizesFefoAndValidates(){long i; try{i=ingredient();}catch(Exception e){throw new RuntimeException(e);} try{var h=MediaType.APPLICATION_JSON; mvc.perform(post("/api/v1/inventory/batches").contentType(h).content("{\"ingredientId\":"+i+",\"amount\":500,\"unit\":\"g\"}" )).andExpect(status().isCreated()); var r=mvc.perform(post("/api/v1/inventory/consumptions").contentType(h).content("{\"ingredientId\":"+i+",\"amount\":0.2,\"unit\":\"kg\"}" )).andExpect(status().isOk()).andExpect(jsonPath("$.amount").value(200)).andExpect(jsonPath("$.unit").value("g")).andExpect(jsonPath("$.allocations[0].remainingAfter").value(300)).andReturn(); long missing=Long.MAX_VALUE; mvc.perform(post("/api/v1/inventory/consumptions").contentType(h).content("{\"ingredientId\":"+missing+",\"amount\":1,\"unit\":\"g\"}" )).andExpect(status().isNotFound()).andExpect(jsonPath("$.code").value("INGREDIENT_NOT_FOUND")); mvc.perform(post("/api/v1/inventory/consumptions").contentType(h).content("{\"ingredientId\":"+i+",\"amount\":0,\"unit\":\"g\"}" )).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("VALIDATION_FAILED")); mvc.perform(get("/v3/api-docs")).andExpect(status().isOk()).andExpect(jsonPath("$.paths['/api/v1/inventory/consumptions'].post.responses['200']").exists()); }catch(Exception e){throw new RuntimeException(e);} } }
